import json, re, urllib.request

pkgs = ["duckdb", "lmdb", "rocksdict", "libsql-experimental", "tinydb",
        "diskcache", "zodb", "apsw", "sqlitedict", "sqlalchemy"]

def get(url):
    with urllib.request.urlopen(url, timeout=25) as r:
        return json.load(r)

def keyver(v):
    return [int(x) if x.isdigit() else x for x in re.split(r'[.\-+]', v)[:3]]

def allows39(spec):
    if not spec: return True
    return "3.9" in spec or "3.8" in spec or "3.7" in spec or "3.6" in spec

for p in pkgs:
    d = get("https://pypi.org/pypi/%s/json" % p)
