    for v, files in d["releases"].items():
        if files and not all(f.get("yanked") for f in files):
            vers.append(v)
    try:
        vers.sort(key=keyver, reverse=True)
    except TypeError:
        vers.sort(reverse=True)
    latest = d["info"]["version"]
